    if (ta) {
      const cur = ta.value;
      ta.value = cur && cur.trim() !== '' ? (cur.includes(text) ? cur : cur + '\n' + text) : text;
      ta.dispatchEvent(new Event('input', { bubbles: true }));
      ta.focus();
      return;
    }
  } catch(e) {}
