  <script>
    (function () {
      try {
        if (window.frameElement) {
          window.frameElement.style.border = 'none';
          var p = window.frameElement.parentElement;
          if (p) { p.style.border = 'none'; p.style.background = 'transparent'; p.style.boxShadow = 'none'; p.style.padding = '0'; }
        }
      } catch (e) {}
      function esc(s) { return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;"); }
      function getMsg() {
        var _get = window.getChatMessages || (window.parent && window.parent.getChatMessages);
        var _id = window.getCurrentMessageId || (window.parent && window.parent.getCurrentMessageId);
        if (typeof _get === 'function' && typeof _id === 'function') {
          try { var ms = _get(_id()); if (ms && ms.length > 0) return ms[0].message; } catch (e) {}
        }
        return null;
      }
      function render() {
        var msg = getMsg();
        if (!msg) return;
        var afterLiwe = msg.split(/<\/liwe>/i).pop();
        var match = afterLiwe.match(/<event>([\s\S]*?)<\/event>/i);
        if (match) {
          var el = document.getElementById('event-target');
          if (!el) return;
          var lines = match[1].trim().split('\n');
          var html = '<div class="timeline-tree">';
          for (var i = 0; i < lines.length; i++) {
            var l = lines[i].trim();
            if (!l) continue;
            if (l.indexOf('|') === -1) {
              html += '<div class="node-item"><div class="node-desc" style="opacity:0.6;">' + esc(l) + '</div></div>';
              continue;
            }
            var moc = '';
            var mMatch = l.match(/\|\s*Mốc\s*:\s*([^|]*)/i);
            if (mMatch) { moc = mMatch[1].trim(); l = l.replace(mMatch[0], '').trim(); }
            var tMatch = l.match(/\[Diễn ra sau:\s*([^\]]+)\]/i);
            var dMatch = l.match(/\[Cách:\s*([^\]]+)\]/i);
            var time = tMatch ? tMatch[1] : '';
            var dist = dMatch ? dMatch[1] : '';
            var rest = l.replace(/^(\[[^\]]+\]\s*)+/, '');
            var parts = rest.split('|').map(function(s){ return s.trim(); });
            var loc = parts[0] || '';
            var title = parts[1] || '';
            var desc = parts[2] || '';
            var nature = parts[3] || '';
            var prio = parts[4] || '';

            var numMatch = prio.match(/(\d+)\s*\/\s*10/);
            var pNum = numMatch ? parseInt(numMatch[1], 10) : 5;
            var dotClass = 'node-dot ' + (pNum >= 8 ? 'crit' : (pNum >= 5 ? 'med' : 'low'));
            var prioClass = 'badge-prio ' + (pNum >= 8 ? 'prio-crit' : (pNum >= 5 ? 'prio-med' : 'prio-low'));
            var prioText = pNum >= 8 ? 'NGUY CẤP ' + pNum + '/10' : pNum + '/10';

            html += '<div class="node-item">' +
                      '<div class="' + dotClass + '"></div>' +
                      '<div class="node-meta">' +
                        (time ? '<span class="badge-time">⏳ ' + esc(time) + '</span>' : '') +
                        (dist ? '<span class="badge-dist">📍 ' + esc(dist) + '</span>' : '') +
                        (prio ? '<span class="' + prioClass + '">' + esc(prioText) + '</span>' : '') +
                      '</div>' +
                      (title ? '<div class="node-title">' + esc(title) + '</div>' : '') +
                      (loc ? '<div class="node-loc">🏛️ ' + esc(loc) + '</div>' : '') +
                      (desc ? '<div class="node-desc">' + esc(desc) + '</div>' : '') +
                      ((nature || moc) ? '<div class="node-nature">' + esc([nature, moc ? '🕒 ' + moc : ''].filter(Boolean).join(' · ')) + '</div>' : '') +
                    '</div>';
          }
          html += '</div>';
          el.innerHTML = html;
        }
      }
      setTimeout(render, 50);
    })();
  </script>
